//! 📶️ Original Energy columns prepare indexed ESF2 bands before bounded range publication.
use super::*;
use semio_framework_math_rank::{ScalarRankCursor,ScalarRankProjection,ScalarRankSource};
const CONTROL:usize=size_of::<usize>()+size_of::<u8>()+size_of::<bool>();
const HEADER:usize=76;
const ROW:usize=24;
pub(super) const STRIDE:usize=65_536;
struct Column<'a>{table:&'a crate::results::SurfaceEnergyTable,index:usize}
impl ScalarRankSource for Column<'_>{
 fn original_identity(&self)->(usize,u64){(self.table as*const _ as usize,self.index as u64)}
 fn len(&self)->usize{self.table.len()}
 fn value_demand(&self,index:usize)->Result<RetirementDemand,ValueError>{if index>=self.len(){return Err(invalid("original rank row exceeds its table"))}Ok(RetirementDemand{copy_bytes:size_of::<crate::model::EntityId>()+size_of::<f64>()+size_of::<f32>(),depth:3,..Default::default()})}
 fn value(&self,index:usize)->Result<f64,ValueError>{let(_,row)=self.table.publication_entry(index).ok_or_else(||invalid("original rank row disappeared"))?;Ok(value(row,self.index)as f64)}
}
fn value(row:&crate::results::SurfaceEnergy,column:usize)->f32{(match column{0=>row.conduction_loss_j,1=>row.conduction_gain_j,2=>row.solar_transmitted_j,_=>row.solar_absorbed_j}/3_600_000.0)as f32}
fn enclosed(mut demand:RetirementDemand)->RetirementDemand{demand.copy_bytes+=CONTROL;demand.depth+=1;demand}
fn child(grant:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-CONTROL,maximum_depth:grant.maximum_depth-1,..grant}}
fn receipt(mut progress:RetainedCloneProgress)->RetainedCloneProgress{progress.copied_bytes+=CONTROL;progress}
/// 🎛️ Each numeric column owns its original rank frontier and its separately retired paged projection.
pub(super) struct EnergySurfacePreparation{cursor:Option<ScalarRankCursor>,columns:[Option<ScalarRankProjection>;4],column:usize,phase:u8,closing:bool}
impl EnergySurfacePreparation{
 pub(super) fn empty()->Self{Self{cursor:None,columns:std::array::from_fn(|_|None),column:0,phase:0,closing:false}}
 pub(super) fn complete(&self)->bool{!self.closing&&self.column==4&&self.cursor.is_none()}
 pub(super) fn is_closing(&self)->bool{self.closing}
 pub(super) fn demand(&self,table:&crate::results::SurfaceEnergyTable)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid("original Energy bands are closing"))}if self.complete(){return Ok(Default::default())}let source=Column{table,index:self.column};Ok(enclosed(match self.cursor.as_ref(){None=>ScalarRankCursor::birth_demand(),Some(cursor)=>match self.phase{0=>cursor.demand(&source)?,1=>cursor.take_demand(),2=>cursor.close_demand()?,_=>RetirementDemand{copy_bytes:size_of::<Option<ScalarRankCursor>>(),depth:1,..Default::default()}}}))}
 pub(super) fn advance(&mut self,table:&crate::results::SurfaceEnergyTable,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{let demand=self.demand(table)?;if self.complete()||!permits(grant,demand){return Ok(Default::default())}let grant=child(grant);let source=Column{table,index:self.column};let progress=if self.cursor.is_none(){let(cursor,progress)=ScalarRankCursor::admit(1e-6,8,grant)?.ok_or_else(||invalid("funded rank admission refused"))?;self.cursor=Some(cursor);progress}else{let cursor=self.cursor.as_mut().unwrap();match self.phase{0=>{let step=cursor.advance(&source,grant)?;if cursor.complete(){self.phase=1;}step.progress()},1=>{let(projection,progress)=cursor.take(grant)?.ok_or_else(||invalid("funded rank handoff refused"))?;self.columns[self.column]=Some(projection);cursor.begin_close();self.phase=2;progress},2=>{let step=cursor.close_step(grant)?;if cursor.terminal_is_empty(){self.phase=3;}step.progress()},_=>{self.cursor=None;self.column+=1;self.phase=0;RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<Option<ScalarRankCursor>>(),..Default::default()}}}};Ok(receipt(progress))}
 pub(super) fn begin_close(&mut self){self.closing=true;if let Some(cursor)=self.cursor.as_mut(){cursor.begin_close();}}
 pub(super) fn close_demands(&self)->Result<RetirementDemand,ValueError>{if let Some(cursor)=self.cursor.as_ref(){return Ok(enclosed(if cursor.terminal_is_empty(){RetirementDemand{copy_bytes:size_of::<Option<ScalarRankCursor>>(),depth:1,..Default::default()}}else{cursor.close_demand()?}))}if let Some(column)=self.columns.iter().find_map(Option::as_ref){let bands=&column.bands;return Ok(enclosed(if !bands.is_empty(){RetirementDemand{copy_bytes:1,depth:bands.next_pop_depth_demand().map_err(|_|invalid("original band pop path differs"))?,..Default::default()}}else if !bands.terminal_is_empty(){RetirementDemand{release_bytes:bands.next_release_allocation_bytes().map_err(|_|invalid("original band backing differs"))?,depth:bands.next_release_depth_demand().map_err(|_|invalid("original band release path differs"))?,..Default::default()}}else{RetirementDemand{copy_bytes:size_of::<Option<ScalarRankProjection>>(),depth:1,..Default::default()}}))}Ok(Default::default())}
 pub(super) fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{if !self.closing{return Err(invalid("original Energy bands close was not begun"))}let demand=self.close_demands()?;if self.terminal_is_empty()||!permits(grant,demand){return Ok(Default::default())}let grant=child(grant);let progress=if let Some(cursor)=self.cursor.as_mut(){if cursor.terminal_is_empty(){self.cursor=None;RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<Option<ScalarRankCursor>>(),..Default::default()}}else{cursor.close_step(grant)?.progress()}}else{let slot=self.columns.iter_mut().find(|slot|slot.is_some()).unwrap();let bands=&mut slot.as_mut().unwrap().bands;if !bands.is_empty(){bands.pop();RetainedCloneProgress{copied_items:1,copied_bytes:1,..Default::default()}}else if !bands.terminal_is_empty(){let mut progress=RetainedCloneProgress{copied_items:1,..Default::default()};progress.released_bytes=bands.release_empty_page(grant.maximum_release_bytes).map_err(|_|invalid("original band release refused"))?.released_bytes;progress}else{*slot=None;RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<Option<ScalarRankProjection>>(),..Default::default()}}};Ok(receipt(progress))}
 pub(super) fn terminal_is_empty(&self)->bool{self.cursor.is_none()&&self.columns.iter().all(Option::is_none)}
}
impl Drop for EnergySurfacePreparation{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Energy bands retain their original paged closure");}}
/// 📦️ Fixed original reads encode one declared range of the complete two-partition publication.
pub(super) struct PreparedSurfacePayload<'a>{pub(super) table:&'a crate::results::SurfaceEnergyTable,pub(super) prepared:&'a EnergySurfacePreparation,pub(super) publication:u64,pub(super) offset:usize}
impl PreparedSurfacePayload<'_>{
 fn extent(&self)->Result<usize,ValueError>{self.table.len().checked_mul(ROW).and_then(|rows|rows.checked_add(HEADER)).ok_or_else(||invalid("ESF2 original extent overflow"))}
 fn word(&self,offset:usize)->Result<([u8;8],usize,usize),ValueError>{let mut word=[0;8];let(length,position)=if offset<4{word[..4].copy_from_slice(b"ESF2");(4,offset)}else if offset<12{let index=(offset-4)/4;let counts=self.table.publication_counts();let count=u32::try_from(counts[index]).map_err(|_|invalid("ESF2 original partition exceeds u32"))?;word[..4].copy_from_slice(&count.to_le_bytes());(4,(offset-4)%4)}else if offset<HEADER{let index=(offset-12)/16;let column=self.prepared.columns[index].as_ref().ok_or_else(||invalid("ESF2 original bands are absent"))?;let value=if ((offset-12)%16)<8{column.minimum}else{column.maximum};word.copy_from_slice(&value.to_le_bytes());(8,(offset-12)%8)}else{let row=(offset-HEADER)/ROW;let field=(offset-HEADER)%ROW;let(id,energy)=self.table.publication_entry(row).ok_or_else(||invalid("ESF2 original row disappeared"))?;if field<4{word[..4].copy_from_slice(&id.0.to_le_bytes());(4,field)}else if field<20{word[..4].copy_from_slice(&value(energy,(field-4)/4).to_le_bytes());(4,(field-4)%4)}else{word[0]=self.prepared.columns[field-20].as_ref().and_then(|column|column.bands.get(row)).copied().ok_or_else(||invalid("ESF2 original band disappeared"))?;(1,0)}};Ok((word,length,position))}
}
impl ToolRunTickPayloadSource for PreparedSurfacePayload<'_>{
 fn update(&self)->semio_framework_tool_run::ToolRunPayloadUpdate{let extent=self.extent().unwrap_or(0);semio_framework_tool_run::ToolRunPayloadUpdate::Range{publication:self.publication,total_bytes:extent as u64,offset:self.offset as u64,chunk_bytes:STRIDE as u32,final_chunk:self.offset+self.byte_len()==extent}}
 fn original_identity(&self)->usize{self.table as*const _ as usize}
 fn byte_len(&self)->usize{self.extent().unwrap_or(0).saturating_sub(self.offset).min(STRIDE)}
 fn range_demands(&self,offset:usize,count:usize)->Result<RetirementDemand,ValueError>{if !self.prepared.complete()||self.publication==0||self.offset>=self.extent()?||count>64||offset.checked_add(count).is_none_or(|end|end>self.byte_len()){return Err(invalid("ESF2 original range differs from its complete rank projection"))}let mut cursor=self.offset+offset;let end=cursor+count;let mut copy=count;let mut depth=1;while cursor<end{let(length,position)=if cursor<12{(4,cursor%4)}else if cursor<HEADER{(8,(cursor-12)%8)}else{let field=(cursor-HEADER)%ROW;if field<20{(4,field%4)}else{let row=(cursor-HEADER)/ROW;let column=self.prepared.columns[field-20].as_ref().unwrap();depth=depth.max(column.bands.next_get_depth_demand(row).map_err(|_|invalid("ESF2 band lookup path differs"))?+3);(1,0)}};copy+=8+2*size_of::<usize>()+size_of::<crate::model::EntityId>()+size_of::<f64>();if cursor>=HEADER{depth=depth.max(3);}cursor+=(length-position).min(end-cursor);}Ok(RetirementDemand{copy_bytes:copy,depth,..Default::default()})}
 fn write_range(&self,offset:usize,target:&mut[u8])->Result<(),ValueError>{self.range_demands(offset,target.len())?;let mut written=0;while written<target.len(){let(word,length,position)=self.word(self.offset+offset+written)?;let count=(length-position).min(target.len()-written);target[written..written+count].copy_from_slice(&word[position..position+count]);written+=count;}Ok(())}
}
